/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: slot, mbid, tags, project, track, release, stored, record
 *   Constants: importId, actor, now, manifest
 * Tests
 *   - the view allowlists evidence: no link, ISRC, recording ID, account, grant, lease, fence, digest or query, even when a stored record carries them
 *   - candidates follow the ranking when ranked and the stored order as incomplete otherwise; an unreadable record is no view
 *   - the view stays within its bounds: 25 candidates and groups, 1000-character text, 20 formats, and out-of-bound groups or values are left out
 *   - needsAnswer and blocking show a tie until a choice, unanswered conflicts, and ignore Album conflicts once an explicit Album reuse makes it an append
 *   - a partial comparison is disclosed, and its single matching group is offered without a preselection but needs no answer
 *   - the view never carries what the strict Web schema refuses: an impossible calendar date shows as unknown and a repeated difference once
 *   - a candidate shows a front-artwork preview only when its fetched release reports one, and never an address
 *   - an iTunes-only candidate shows as such with its collection ID, whether it was checked against MusicBrainz and an artwork flag, never its address, storefront or localized names
 *   - the iTunes status: not queried without a stage or once a run ended before it answered, running or retrying while an iTunes request waits, else as the stage ended
 * @end-catalog */

/**
 * The administrator's lookup view without a database: the allowlist (no links, recording or account data, grant, lease, fence
 * or queries), ranked and unranked candidate order, bounds, the applied values with re-read conflicts, stale files and what
 * Publish waits for. All names, identifiers and accounts are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { ImportManifest } from '../../src/administration/import/adminImportContract';
import { defaultDraftV2, type ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import type { MusicBrainzRelease } from '../../src/administration/lookup/lookupContract';
import { applyPreselectedLookup } from '../../src/administration/lookup/lookupValueApplication';
import { importLookupView } from '../../src/administration/lookup/lookupView';
import { itunesRelease } from '../../src/administration/lookup/lookupItunesStage';
import { rankLookupWithinBudget, type MetadataLookupRecord, type StoredLookupCandidate } from '../../src/administration/lookup/metadataLookupRecord';

const importId = '0000000000000000000000d2', actor = '0000000000000000000000e1';
const now = new Date('2026-10-19T00:00:00Z');
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const mbid = (index: number) => `0000000b-0000-4000-8000-${String(index).padStart(12, '0')}`;
const manifest: ImportManifest = { rootLabel: 'Synthetic Folder', files: [0, 1].map(index => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 })) };
const tags = (index: number) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null, discNumber: null, trackNumber: null,
    durationMs: 200_000 + (index + 1) * 10_000, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [] });
const project = (): AdminImportDocument => ({ _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: defaultDraftV2(manifest), draftOrigins: {}, manifest,
    media: { assets: manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: mbid(500 + index), state: 'ready', sha256: 'a'.repeat(64), duration: null, tags: tags(index) }) as unknown as ImportAsset) },
    revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [], updatedAt: new Date(0) }) as unknown as AdminImportDocument;
const track = (position: number, title: string) => ({ position, number: String(position), title, lengthMs: 200_000 + position * 10_000, recordingId: mbid(900 + position), isrcs: ['JPXX02600001'] });
const release = (id: number, extra: Partial<MusicBrainzRelease> = {}): MusicBrainzRelease => ({
    releaseId: mbid(id), releaseGroupId: mbid(100 + id), title: 'Synthetic Album', status: 'Official',
    artistCredit: [{ name: 'Synthetic Lead', joinPhrase: ' & ', artistId: mbid(1), artistName: 'Synthetic Lead' }, { name: 'Synthetic Second', joinPhrase: '', artistId: mbid(2), artistName: 'Synthetic Second' }],
    labels: [{ name: `Label ${id}`, labelId: mbid(10), catalogNumber: `SYN-00${id}` }], barcode: '4006381333931', barcodeText: '4006381333931', country: 'JP',
    date: { year: 2021, month: 5, day: 1 }, primaryType: 'Album', secondaryTypes: [], trackCount: 2, groupFirstReleaseDate: { year: 2020, month: null, day: null },
    media: [{ position: 1, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }], frontArtwork: true, ...extra
});
const stored = (value: MusicBrainzRelease, details: StoredLookupCandidate['details'] = 'fetched'): StoredLookupCandidate => ({ key: `musicbrainz:${value.releaseId}`, source: 'musicbrainz',
    releaseId: value.releaseId, basis: 'albumText', summary: null, release: details === 'fetched' ? value : null, details });
function record(doc: AdminImportDocument, candidates: StoredLookupCandidate[], extra: Partial<MetadataLookupRecord> = {}): MetadataLookupRecord {
    const searchComplete = extra.searchComplete ?? true, ranked = rankLookupWithinBudget(candidates, doc, now, { searchComplete });
    return { _id: doc._id, run: 2, state: 'complete', issue: null, outcome: 'candidates', operationId: mbid(600), actorId: actor, grantSource: 'submit',
        grantExpiresAt: new Date(now.getTime() + 60_000), automatic: false, input: { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Album' } },
        queries: [{ kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Album' }, basis: 'submitted' } as never], queryIndex: 1, phase: 'done',
        fileSetDigest: 'f'.repeat(64), files: [], attempts: { musicbrainz: 1 }, retryAt: null, candidates: ranked.candidates, ranking: ranked.ranking, searchComplete, applied: null,
        staleSlotIds: [slot(1), 'removed-slot'], automaticRuns: 1, folderUsed: false, leaseOwner: 'worker-secret', leaseUntil: now, createdAt: now, updatedAt: now, completedAt: now, ...extra };
}

test('the view allowlists evidence: no link, ISRC, recording ID, account, grant, lease, fence, digest or query, even when a stored record carries them', () => {
    const doc = project(), injected = record(doc, [stored(release(1))]);
    (doc as unknown as Record<string, unknown>).lookupGate = { fence: 7, run: 2, state: 'complete', blocking: false };
    const raw = injected as unknown as Record<string, unknown>;
    raw.url = 'https://musicbrainz.org/release/x'; raw.artworkUrl = 'https://is1-ssl.mzstatic.com/x.jpg';
    (raw.candidates as Record<string, unknown>[])[0].url = 'https://example.invalid/';
    ((raw.candidates as { release: Record<string, unknown> }[])[0].release).artworkUrl = 'https://coverartarchive.org/x';
    (raw.ranking as Record<string, unknown>).secret = 'https://example.invalid/ranking';
    const applied = applyPreselectedLookup(doc, injected, now).record;
    (applied.applied as unknown as Record<string, unknown>).url = 'https://example.invalid/applied';
    const view = importLookupView(applied, doc)!, text = JSON.stringify(view);
    for (const secret of ['://', 'isrc', 'JPXX', 'recordingId', 'actorId', actor, 'grantExpiresAt', 'fence', 'leaseOwner', 'worker-secret', 'fileSetDigest', 'queries',
        'musicBrainzReleaseSearch', 'operationId', 'grantSource', 'automaticRuns', 'removed-slot', 'Url', 'secret']) assert.equal(text.includes(secret), false, secret);
    assert.deepEqual(Object.keys(view).sort(), ['applied', 'blocking', 'candidates', 'disclosure', 'groups', 'input', 'issue', 'itunes', 'needsAnswer', 'outcome', 'preselection', 'run',
        'staleFiles', 'state'].sort());
    assert.deepEqual(view.candidates[0], { key: `musicbrainz:${mbid(1)}`, releaseId: mbid(1), source: 'musicbrainz', notChecked: false, status: 'matching', title: 'Synthetic Album', artist: 'Synthetic Lead & Synthetic Second',
        label: 'Label 1', catalogNumber: 'SYN-001', barcode: '4006381333931', country: 'JP', date: { year: 2021, month: 5, day: 1 }, formats: ['CD'], trackCount: 2,
        comparison: { trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 1 }, differences: [], unknownLocalDurations: 0, unknownCandidateDurations: 0 },
        groupKey: view.groups[0].groupKey, artistMismatch: false, artwork: true });
    assert.deepEqual([view.run, view.state, view.issue, view.outcome, view.input, view.preselection, view.disclosure, view.staleFiles],
        [2, 'complete', null, 'candidates', { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Album' } },
            { candidateKey: `musicbrainz:${mbid(1)}`, basis: 'onlyMatchingGroup', artistMismatch: false, notChecked: false }, { unknownLocalDurations: 0, unknownLocalDiscNumbers: 2, partialComparison: false }, [slot(1)]]);
    // A proposal names each credited MusicBrainz artist and the label's.
    assert.deepEqual(view.groups[0].proposal.artists, [{ name: 'Synthetic Lead', role: 'primary', joinPhrase: ' & ', musicBrainzId: mbid(1) },
        { name: 'Synthetic Second', role: 'primary', joinPhrase: null, musicBrainzId: mbid(2) }]);
    assert.equal(view.groups[0].proposal.labelMusicBrainzId, mbid(10));
    assert.deepEqual([view.applied!.choice, view.applied!.basis, view.applied!.candidateKey, view.applied!.values.map(value => value.path).slice(0, 2), view.applied!.conflicts, view.applied!.flagged,
        view.applied!.source, view.applied!.notChecked], ['preselected', 'onlyMatchingGroup', `musicbrainz:${mbid(1)}`, ['album.title', 'album.artists'], [], [], 'musicbrainz', false]);
    assert.deepEqual([view.needsAnswer, view.blocking, view.itunes], [{ tie: false, conflicts: [] }, false, 'notQueried']);
});

test('candidates follow the ranking when ranked and the stored order as incomplete otherwise; an unreadable record is no view', () => {
    const doc = project(), ranked = record(doc, [stored(release(3)), stored(release(1), 'failed'), stored(release(2, { media: [{ position: 1, format: 'CD', tracks: [track(1, 'Only')] }] }))]);
    assert.deepEqual(importLookupView(ranked, doc)!.candidates.map(candidate => [candidate.releaseId, candidate.status]),
        [[mbid(3), 'matching'], [mbid(2), 'notMatching'], [mbid(1), 'incomplete']]);
    const running: MetadataLookupRecord = { ...ranked, state: 'running', outcome: null, ranking: null, phase: 'details' };
    const view = importLookupView(running, doc)!;
    assert.deepEqual(view.candidates.map(candidate => [candidate.releaseId, candidate.status, candidate.comparison]),
        [[mbid(3), 'incomplete', null], [mbid(1), 'incomplete', null], [mbid(2), 'incomplete', null]]);
    assert.deepEqual([view.groups, view.preselection, view.disclosure, view.blocking, view.needsAnswer], [[], null, null, true, { tie: false, conflicts: [] }]);
    // A failed candidate shows its search summary when it has one.
    const summarised = { ...running, candidates: running.candidates.map(candidate => candidate.details === 'failed'
        ? { ...candidate, summary: { ...release(1), score: 90, trackCount: 12, media: [{ format: 'Digital Media', trackCount: 12 }] } } as unknown as StoredLookupCandidate : candidate) };
    assert.deepEqual(((candidate) => [candidate.title, candidate.trackCount, candidate.formats])(importLookupView(summarised, doc)!.candidates[1]), ['Synthetic Album', 12, ['Digital Media']]);
    for (const broken of [{ state: 'paused' }, { run: 0 }, { run: '2' }, { input: { trigger: 'filename', submitted: null } }, { input: null }])
        assert.equal(importLookupView({ ...ranked, ...broken } as unknown as MetadataLookupRecord, doc), null, JSON.stringify(broken));
});

test('the view stays within its bounds: 25 candidates and groups, 1000-character text, 20 formats, and out-of-bound groups or values are left out', () => {
    const doc = project(), many = Array.from({ length: 30 }, (_unused, index) => stored(release(20 + index, { labels: [{ name: `Label ${index}`, labelId: null, catalogNumber: null }] })));
    const base = record(doc, many.slice(0, 25));
    const raw = { ...base, candidates: [...base.candidates, ...many.slice(25)], ranking: { ...base.ranking!, candidates: [...base.ranking!.candidates, ...many.slice(25).map(candidate => ({ ...base.ranking!.candidates[0], key: candidate.key, releaseId: candidate.releaseId }))],
        groups: [...base.ranking!.groups, ...base.ranking!.groups.slice(0, 5)] } };
    const view = importLookupView(raw, doc)!;
    assert.deepEqual([view.candidates.length, view.groups.length], [25, 25]);
    const long = release(60, { title: 't'.repeat(1001), media: [...Array.from({ length: 25 }, (_unused, index) => ({ position: index + 1, format: index === 0 ? 'f'.repeat(101) : 'CD', tracks: [] })),
        { position: 26, format: 'CD', tracks: [track(1, 'First Song'), track(2, 'Second Song')] }] });
    const shown = importLookupView(record(doc, [stored(long)]), doc)!;
    assert.deepEqual([shown.candidates[0].title, shown.candidates[0].formats.length, shown.groups], [null, 20, []], 'a group whose proposal is over the bounds is left out');
    const applied = applyPreselectedLookup(doc, record(doc, [stored(release(1))]), now).record;
    applied.applied!.conflicts = [{ path: 'album.label', lookup: { name: 'Label 1', musicBrainzId: null }, slotId: null, answer: null },
        { path: 'album.title', lookup: 'x'.repeat(301), slotId: null, answer: null }, { path: 'album.visibility' as never, lookup: 'hidden', slotId: null, answer: null },
        { path: `tracks.${mbid(77)}.title`, lookup: 'Elsewhere', slotId: mbid(77), answer: null }, { path: 'album.releaseDate', lookup: null, slotId: null, answer: null }];
    applied.applied!.flagged = [{ path: 'album.artists', reason: 'placeholder' }, { path: 'album.label', reason: 'unknown' as never }];
    const conflicted = importLookupView(applied, doc)!;
    assert.deepEqual(conflicted.applied!.conflicts, [{ path: 'album.label', slotId: null, lookup: { name: 'Label 1', musicBrainzId: null }, answer: null, musicBrainzId: false }]);
    // An ID conflict's lookup value carries the release's IDs, which the view reads as introduced, and is marked as one.
    applied.applied!.conflicts = [{ path: 'album.label', lookup: { name: 'Label 1', musicBrainzId: mbid(10) }, slotId: null, answer: null, musicBrainzId: true },
        { path: 'album.artists', lookup: [{ key: slot(5), name: 'Lead', role: 'primary', joinPhrase: null, musicBrainzId: '89ad4ac3-39f7-470e-963a-56509c546377' }], slotId: null, answer: null }];
    assert.deepEqual(importLookupView(applied, doc)!.applied!.conflicts, [{ path: 'album.label', slotId: null, lookup: { name: 'Label 1', musicBrainzId: mbid(10) }, answer: null, musicBrainzId: true }],
        'a placeholder ID is never shown');
    assert.deepEqual(conflicted.applied!.flagged, [{ path: 'album.artists', reason: 'placeholder' }]);
});

test('needsAnswer and blocking show a tie until a choice, unanswered conflicts, and ignore Album conflicts once an explicit Album reuse makes it an append', () => {
    const doc = project(), tie = record(doc, [stored(release(1)), stored(release(2))]);
    assert.deepEqual([importLookupView(tie, doc)!.needsAnswer, importLookupView(tie, doc)!.blocking], [{ tie: true, conflicts: [] }, true]);
    const mine = project();
    (mine.draft as ImportDraftV2).album.label = { name: 'Mine', musicBrainzId: null }; mine.draftOrigins = { 'album:label': 'administrator' };
    const conflicted = applyPreselectedLookup(mine, record(mine, [stored(release(1))]), now).record;
    assert.deepEqual([importLookupView(conflicted, mine)!.needsAnswer, importLookupView(conflicted, mine)!.blocking], [{ tie: false, conflicts: ['album.label'] }, true]);
    mine.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: 'c'.repeat(24), candidateRevision: 'r' }] as AdminImportDocument['decisions'];
    assert.deepEqual([importLookupView(conflicted, mine)!.needsAnswer, importLookupView(conflicted, mine)!.blocking], [{ tie: false, conflicts: [] }, false]);
    for (const state of ['queued', 'running', 'retrying'] as const) assert.equal(importLookupView({ ...tie, state }, doc)!.blocking, true, state);
    for (const state of ['stopped', 'unavailable', 'superseded'] as const) assert.equal(importLookupView({ ...tie, state }, doc)!.blocking, false, state);
});

test('a partial comparison is disclosed, and its single matching group is offered without a preselection but needs no answer', () => {
    const doc = project(), partial = record(doc, [stored(release(1))], { searchComplete: false });
    const view = importLookupView(applyPreselectedLookup(doc, partial, now).record, doc)!;
    assert.deepEqual([view.groups.length, view.preselection, view.applied, view.disclosure, view.needsAnswer, view.blocking],
        [1, null, null, { unknownLocalDurations: 0, unknownLocalDiscNumbers: 2, partialComparison: true }, { tie: false, conflicts: [] }, false]);
    // Two matching groups of a partial comparison are a tie as before.
    const two = record(doc, [stored(release(1)), stored(release(2, { title: 'Synthetic Other' }))], { searchComplete: false });
    assert.deepEqual([two.ranking!.groups.length, importLookupView(two, doc)!.needsAnswer], [2, { tie: true, conflicts: [] }]);
    // A ranking stored before the field shows a complete comparison, as its own preselection already decided.
    const legacy = record(doc, [stored(release(1))]);
    delete (legacy.ranking!.disclosure as { partialComparison?: boolean }).partialComparison;
    assert.deepEqual(importLookupView(legacy, doc)!.disclosure, { unknownLocalDurations: 0, unknownLocalDiscNumbers: 2, partialComparison: false });
});

test('the view never carries what the strict Web schema refuses: an impossible calendar date shows as unknown and a repeated difference once', () => {
    const doc = project(), base = record(doc, [stored(release(1, { date: { year: 2021, month: 2, day: 30 } }))]);
    const raw = { ...base, ranking: { ...base.ranking!,
        candidates: base.ranking!.candidates.map(entry => ({ ...entry, comparison: { ...entry.comparison!, differences: ['duration', 'duration', 'trackCount', 'unknown', 'duration'] } })),
        groups: base.ranking!.groups.map(group => ({ ...group, proposal: { ...group.proposal, releaseDate: { year: 2019, month: 2, day: 29 } } })) } };
    const view = importLookupView(raw as unknown as MetadataLookupRecord, doc)!;
    assert.deepEqual([view.candidates[0].date, view.candidates[0].comparison!.differences, view.groups[0].proposal.releaseDate], [null, ['duration', 'trackCount'], null]);
    // A Gregorian leap day and month or year precision stay; a century that is no leap year has no 29 February.
    for (const [date, shown] of [[{ year: 2020, month: 2, day: 29 }, true], [{ year: 2000, month: 2, day: 29 }, true], [{ year: 1900, month: 2, day: 29 }, false],
        [{ year: 2021, month: 4, day: 31 }, false], [{ year: 2021, month: 2, day: null }, true], [{ year: 2021, month: null, day: null }, true], [{ year: 2021, month: null, day: 1 }, false]] as const)
        assert.deepEqual(importLookupView(record(doc, [stored(release(2, { date }))]), doc)!.candidates[0].date, shown ? date : null, JSON.stringify(date));
});

test('a candidate shows a front-artwork preview only when its fetched release reports one, and never an address', () => {
    const doc = project();
    const candidates = [stored(release(1)), stored(release(2, { frontArtwork: false })), stored(release(3, { frontArtwork: null })), stored(release(4), 'pending'),
        { ...stored(release(5)), release: { ...release(5), frontArtwork: 'true' as unknown as boolean } }];
    const view = importLookupView(record(doc, candidates), doc)!;
    assert.deepEqual(Object.fromEntries(view.candidates.map(candidate => [candidate.releaseId, candidate.artwork])),
        { [mbid(1)]: true, [mbid(2)]: false, [mbid(3)]: false, [mbid(4)]: false, [mbid(5)]: false });
    const text = JSON.stringify(view);
    for (const address of ['coverartarchive', 'archive.org', 'front-', '://']) assert.equal(text.includes(address), false, address);
});

test('an iTunes-only candidate shows as such with its collection ID, whether it was checked against MusicBrainz and an artwork flag, never its address, storefront or localized names', () => {
    const doc = project();
    const value = itunesRelease({ collectionId: '1613862586', collectionName: 'Synthetic Album', artistName: 'Synthetic Ensemble', trackCount: 2, releaseDate: { year: 2022, month: 3, day: 24 },
        country: 'JPN', artworkUrl: 'https://is1-ssl.mzstatic.com/image/thumb/Music/v4/a/b/c/x.jpg/100x100bb.jpg' }, [1, 2].map(n => ({ trackId: `9${n}`, collectionId: '1613862586',
        collectionName: null, trackName: n === 1 ? 'First Song' : 'Second Song', artistName: 'Synthetic Ensemble', discNumber: 1, discCount: 1, trackNumber: n, trackTimeMillis: 200_000 + n * 10_000 })), '4580760834214');
    const itunes = (check: 'noRelease' | 'unavailable' | 'notRun'): StoredLookupCandidate => ({ key: 'itunes:1613862586', source: 'itunes', releaseId: '1613862586', basis: 'itunes', summary: null,
        release: value, details: 'fetched', itunes: { storefront: 'jp', artworkUrl: 'https://is1-ssl.mzstatic.com/image/thumb/Music/v4/a/b/c/x.jpg/100x100bb.jpg', check } });
    const stage = { reason: 'searchUnavailable' as const, text: null, requests: [], requestIndex: 0, bridge: [], bridgeIndex: 0, bridgeOutcomes: [], state: 'answered' as const, complete: true, finalized: true,
        items: [{ key: 'collection:1613862586', kind: 'collection' as const, collectionId: '1613862586', names: [{ storefront: 'us' as const, title: 'A', artist: 'Romanized Secret' },
            { storefront: 'jp' as const, title: 'B', artist: '日本語の秘密' }], barcode: null, bridge: 'unavailable' as const, collection: 'fetched' as const }] };
    const run = applyPreselectedLookup(doc, record(doc, [itunes('unavailable')], { issue: 'sourceUnavailable', itunesStage: stage }), now).record;
    const view = importLookupView(run, doc)!, text = JSON.stringify(view);
    assert.deepEqual(view.candidates[0], { key: 'itunes:1613862586', releaseId: '1613862586', source: 'itunes', notChecked: true, status: 'matching', title: 'Synthetic Album',
        artist: 'Synthetic Ensemble', label: null, catalogNumber: null, barcode: '4580760834214', country: null, date: { year: 2022, month: 3, day: 24 }, formats: [], trackCount: 2,
        comparison: { trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 1 }, differences: [], unknownLocalDurations: 0, unknownCandidateDurations: 0 },
        groupKey: view.groups[0].groupKey, artistMismatch: false, artwork: true });
    assert.deepEqual([view.preselection, view.applied!.source, view.applied!.notChecked, view.applied!.releaseId, view.itunes],
        [{ candidateKey: 'itunes:1613862586', basis: 'onlyMatchingGroup', artistMismatch: false, notChecked: true }, 'itunes', true, '1613862586', 'answered']);
    for (const secret of ['mzstatic', '://', 'storefront', '"jp"', 'Romanized Secret', '日本語の秘密', 'artworkUrl', 'JPN']) assert.equal(text.includes(secret), false, secret);
    // A candidate MusicBrainz ruled out is not flagged; one whose bridge did not run is.
    assert.deepEqual(['noRelease', 'notRun'].map(check => importLookupView(record(doc, [itunes(check as 'noRelease')]), doc)!.candidates[0].notChecked), [false, true]);
    // A key and release ID that disagree, or a source that contradicts the key, is no candidate.
    for (const broken of [{ releaseId: '1613862587' }, { releaseId: '01613862586', key: 'itunes:01613862586' }, { source: 'musicbrainz' }, { key: `musicbrainz:${mbid(1)}` }]) {
        assert.deepEqual(importLookupView({ ...record(doc, []), ranking: null, candidates: [{ ...itunes('noRelease'), ...broken } as StoredLookupCandidate] }, doc)!.candidates, [], JSON.stringify(broken));
    }
});

test('the iTunes status: not queried without a stage or once a run ended before it answered, running or retrying while an iTunes request waits, else as the stage ended', () => {
    const doc = project(), base = record(doc, []);
    const stage = (state: 'running' | 'answered' | 'unavailable') => ({ reason: 'noMatch' as const, text: null, requests: [], requestIndex: 0, items: [], bridge: null, bridgeIndex: 0,
        bridgeOutcomes: [], state, complete: true, finalized: false });
    const status = (extra: Partial<MetadataLookupRecord>) => importLookupView({ ...base, ...extra }, doc)!.itunes;
    assert.deepEqual([status({}), status({ itunesStage: null }), status({ itunesStage: 'x' as never })], ['notQueried', 'notQueried', 'notQueried']);
    assert.deepEqual([status({ state: 'running', phase: 'itunes', itunesStage: stage('running') }), status({ state: 'retrying', phase: 'itunes', itunesStage: stage('running') }),
        status({ state: 'retrying', phase: 'bridge', itunesStage: stage('answered') }), status({ state: 'retrying', phase: 'itunes', itunesStage: stage('answered') }),
        status({ state: 'running', phase: 'itunes', itunesStage: stage('answered') }), status({ state: 'stopped', phase: 'itunes', itunesStage: stage('running') }),
        status({ state: 'complete', itunesStage: stage('answered') }), status({ state: 'complete', itunesStage: stage('unavailable') })],
    ['running', 'retrying', 'answered', 'retrying', 'running', 'notQueried', 'answered', 'unavailable']);
    // An applied candidate of an earlier release's record shows as MusicBrainz's, and a source without its key is ignored.
    const applied = { run: 1, candidateKey: `musicbrainz:${mbid(1)}`, releaseId: mbid(1), choice: 'chosen', basis: 'chosen', values: [], conflicts: [], flagged: [], source: 'itunes', notChecked: true };
    assert.deepEqual(((view) => [view.source, view.notChecked])(importLookupView({ ...base, applied: applied as never }, doc)!.applied!), ['musicbrainz', false]);
});
